    const int n = DrawLen(text, len);
    if (n <= 0) return 0;                                                          // 0x0047824d, 0x0047826d
    const int run = kDrawMarkupRun(self, nullptr, text, n);                        // 0x00478273
    const int x = rect[2] - run;                                                   // 0x00478278..0x0047827f
